<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>悦容美发美容 - 广州专业形象设计</title>
    <style>
        :root {
            --primary: #b07d4d;
            --primary-dark: #8a5e3a;
            --bg-light: #f9f8f6;
            --text-dark: #333333;
            --text-gray: #666666;
            --white: #ffffff;
            --border-radius: 8px;
            --shadow: 0 4px 12px rgba(0, 0, 0, 0.08);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
        }

        body {
            background-color: var(--bg-light);
            color: var(--text-dark);
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        img {
            max-width: 100%;
            display: block;
        }

        /* Header */
        header {
            background-color: var(--white);
            box-shadow: 0 2px 8px rgba(0,0,0,0.05);
            position: sticky;
            top: 0;
            z-index: 1000;
        }

        nav {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 1rem 20px;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: bold;
            color: var(--primary);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .nav-links {
            display: flex;
            gap: 30px;
        }

        .nav-links a {
            font-size: 1rem;
            font-weight: 500;
            transition: color 0.3s;
        }

        .nav-links a:hover {
            color: var(--primary);
        }

        .btn-book {
            background-color: var(--primary);
            color: var(--white);
            padding: 0.6rem 1.5rem;
            border-radius: 20px;
            transition: background 0.3s;
        }

        .btn-book:hover {
            background-color: var(--primary-dark);
            color: var(--white);
        }

        /* Hero Section */
        .hero {
            position: relative;
            height: 600px;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            background-image: url('https://picsum.photos/seed/salonhero/1600/900');
            background-size: cover;
            background-position: center;
            color: var(--white);
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.5);
        }

        .hero-content {
            position: relative;
            z-index: 1;
            max-width: 800px;
            padding: 20px;
        }

        .hero h1 {
            font-size: 3rem;
            margin-bottom: 1rem;
            letter-spacing: 2px;
        }

        .hero p {
            font-size: 1.25rem;
            margin-bottom: 2rem;
            opacity: 0.9;
        }

        /* Featured Services */
        .section {
            padding: 80px 20px;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
        }

        .section-header {
            text-align: center;
            margin-bottom: 50px;
        }

        .section-header h2 {
            font-size: 2.2rem;
            color: var(--text-dark);
            margin-bottom: 10px;
        }

        .section-header p {
            color: var(--text-gray);
        }

        .feature-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }

        .feature-card {
            background: var(--white);
            border-radius: var(--border-radius);
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: transform 0.3s;
        }

        .feature-card:hover {
            transform: translateY(-5px);
        }

        .feature-card img {
            width: 100%;
            height: 250px;
            object-fit: cover;
        }

        .feature-content {
            padding: 25px;
        }

        .feature-content h3 {
            font-size: 1.4rem;
            margin-bottom: 10px;
        }

        .feature-content p {
            color: var(--text-gray);
            margin-bottom: 20px;
        }

        .price-tag {
            color: var(--primary);
            font-weight: bold;
            font-size: 1.2rem;
        }

        /* Testimonial/Why Choose */
        .why-us {
            background-color: var(--white);
        }

        .split-layout {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            gap: 50px;
        }

        .split-text {
            flex: 1;
            min-width: 300px;
        }

        .split-text ul {
            list-style: none;
            margin-top: 20px;
        }

        .split-text li {
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .split-text li::before {
            content: '✓';
            color: var(--primary);
            font-weight: bold;
        }

        .split-image {
            flex: 1;
            min-width: 300px;
        }

        .split-image img {
            border-radius: var(--border-radius);
            box-shadow: var(--shadow);
        }

        /* Footer */
        footer {
            background-color: #222;
            color: #ccc;
            padding: 50px 20px 20px;
        }

        .footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 40px;
            padding-bottom: 40px;
            border-bottom: 1px solid #444;
        }

        .footer-col h4 {
            color: var(--white);
            margin-bottom: 20px;
            font-size: 1.1rem;
        }

        .footer-col p, .footer-col a {
            margin-bottom: 10px;
            display: block;
            font-size: 0.95rem;
            color: #ccc;
        }

        .footer-col a:hover {
            color: var(--white);
        }

        .copyright {
            text-align: center;
            padding-top: 20px;
            font-size: 0.85rem;
        }

        /* Mobile Adjustments */
        @media (max-width: 768px) {
            .nav-links {
                display: none; /* Simplified for mobile view */
            }
            .hero h1 {
                font-size: 2rem;
            }
        }
    </style>
</head>
